  "Huecos: {openLength}/{slots}. La copia que dejas va sin entrenamiento, estrellas ni ascensión: tu futbolista se queda con todo. Un HÉROE ascendido sí puede dejar sus copias repetidas. No se pueden dejar Leyenda ni futbolistas de evento, ni repetir un cambio.": "Slots: {openLength}/{slots}. The copy you leave goes without training, stars or ascension: your player keeps all of it. An ascended HERO can leave its duplicate copies. Legends and event players can't be left, and a trade can't be repeated.",
