  "Cuenta online": "Online account",
  "El servicio online no está activado en esta versión. Tu progreso se guarda en este navegador (Ajustes » Exportar/Importar para llevarlo a otro). Con el servicio activo podrás entrar con Google, reservar tu nombre en todo el mundo, aparecer en el ranking global y guardar en la nube.": "The online service is not enabled in this version. Your progress is saved in this browser (Settings » Export/Import to take it to another one). With the service on you can sign in with Google, claim your worldwide name, appear on the global ranking and save to the cloud.",
  "Estás jugando como invitado: tu progreso se guarda solo en este navegador. Entra con Google para reservar tu nombre en todo el mundo, aparecer en el ranking y guardar en la nube. Tu correo es privado: nunca aparece en el ranking.": "You are playing as a guest: your progress is only saved in this browser. Sign in with Google to claim your worldwide name, appear on the ranking and save to the cloud. Your email is private: it never shows on the ranking.",
