  "Valores centrados en 60: por encima suman, por debajo restan. Cada técnica usa las estadísticas de su futbolista. Lo propio llega a 99; con un Aura, hasta {EFFECTIVE_STAT_MAX}.": "Values centred on 60: above it they add, below it they take away. Each technique uses its player's stats. Own stats reach 99; with an Aura, up to {EFFECTIVE_STAT_MAX}.",
  "Banner de agradecimiento": "Thank-you Banner",
  "Ataque a los Titanes, Los Siete Pecados Capitales y Axel Encapuchado · {cost} fichas de evento la tirada": "Attack on Titan, The Seven Deadly Sins and Hooded Axel · {cost} event tokens per pull",
