  "NUEVO": "NEW",
  ": se desbloquea para siempre y ya puede ir en Mi Equipo.": ": unlocked for good and can now go in My Team.",
  "Duplicado": "Duplicate",
  ": sirve para ascender al futbolista; si ya no puede ascender más, se convierte en monedas.": ": it is used to ascend the player; if they can't ascend any more, it turns into coins.",
  "Los duplicados también pagan la <b>ascensión</b> de cualquier futbolista (Fix 1.53): cada ascensión sube una rareza y cuesta según la rareza desde la que sube (Común {ascenso}, Raro {ascenso2}, Épico {ascenso3}, Legendario {ascenso4}). Al llegar a Mítico, el HÉROE cuesta según la rareza con la que nació: Común {heroe}, Raro {heroe2}, Épico {heroe3}, Legendario {heroe4}, Mítico {heroe5} y Leyenda {heroe6}. Después, cada HÉROE gana hasta {HERO_STARS_MAX} estrellas de héroe (Mítico {estrella} duplicados cada una).": "Duplicates also pay for any player's <b>ascension</b>: each ascension raises one rarity and costs according to the rarity it rises from (Common {ascenso}, Rare {ascenso2}, Epic {ascenso3}, Legendary {ascenso4}). On reaching Mythic, HERO costs according to the rarity it was born with: Common {heroe}, Rare {heroe2}, Epic {heroe3}, Legendary {heroe4}, Mythic {heroe5} and Legend {heroe6}. After that, each HERO earns up to {HERO_STARS_MAX} hero stars (Mythic {estrella} duplicates each).",
  "Con {MAX_STARS} estrellas y HÉROE, cada copia da monedas (de {comun} a {leyenda} según la rareza).": "With {MAX_STARS} stars and HERO, each copy gives coins (from {comun} to {leyenda} depending on the rarity).",
  "Fichas = máquina de cápsulas · Monedas = mejoras y tiendas. Gráficos de la máquina: Inazuma Eleven 3 (hoja de The Spriters Resource, ripeada por Avegaille), recurso local.": "Tokens = capsule machine · Coins = upgrades and shops. Machine graphics: Inazuma Eleven 3 (sheet from The Spriters Resource, ripped by Avegaille), local resource.",
  "Duplicado · +{refund} monedas": "Duplicate · +{refund} coins",
