  "REPERTORIO": "MOVESET",
  "Cada futbolista solo usa su propio repertorio. Aquí desbloqueas sus técnicas y compras <b>manuales</b> de daño permanente (subir de nivel una técnica en partida es aparte).": "Each player only uses their own moveset. Here you unlock their techniques and buy permanent damage <b>manuals</b> (levelling a technique up in a run is separate).",
  "Bonificaciones para todo el equipo. No cambian la equipación Raimon que se ve en combate.": "Bonuses for the whole team. They don't change the Raimon kit seen in battle.",
  "InaZurvivors — Proyecto de fans no oficial": "InaZurvivors — Unofficial fan project",
  "InaZurvivors es un fangame independiente y gratuito desarrollado por AstraStorm17, inspirado en la franquicia Inazuma Eleven.": "InaZurvivors is a free, independent fangame developed by AstraStorm17, inspired by the Inazuma Eleven franchise.",
  "Inazuma Eleven, sus personajes, nombres, diseños, logotipos, música y materiales originales son propiedad de LEVEL-5 y/o sus respectivos titulares.": "Inazuma Eleven, its characters, names, designs, logos, music and original materials are the property of LEVEL-5 and/or their respective owners.",
  "Este proyecto no está afiliado, patrocinado ni aprobado por LEVEL-5.": "This project is not affiliated with, sponsored or endorsed by LEVEL-5.",
  "El código y los materiales originales desarrollados específicamente para InaZurvivors pertenecen a sus respectivos autores.": "The code and original materials made specifically for InaZurvivors belong to their respective authors.",
  "Los recursos gráficos y sonoros de terceros conservan sus derechos originales.": "Third-party graphics and sound keep their original rights.",
  "La inclusión de créditos y este aviso no implica la existencia de una licencia o autorización para distribuir material protegido.": "Including credits and this notice does not imply any licence or authorisation to distribute protected material.",
  "Desarrollo": "Development",
  "Diseño, dirección y desarrollo: AstraStorm17.": "Design, direction and development: AstraStorm17.",
  "Programación con asistencia de Claude (Anthropic).": "Programming assisted by Claude (Anthropic).",
  "Recursos de terceros y su procedencia": "Third-party resources and their origin",
  "Futbolistas, retratos, cuerpos, escudos, objetos, arenas y música: Inazuma Eleven 2 (LEVEL-5), extraídos de una copia propia del juego.": "Players, portraits, bodies, crests, items, arenas and music: Inazuma Eleven 2 (LEVEL-5), extracted from an owned copy of the game.",
  "Futbolistas, retratos y escudos de las sagas Mundial, GO, Chrono Stones, Galaxy, Ares y Orion: Inazuma Eleven 3 (LEVEL-5) con el parche de fans «Great Road of Heroes 3.1». Autoría del parche: no verificada; base y añadidos del parche no se pueden separar.": "Players, portraits and crests of the World, GO, Chrono Stones, Galaxy, Ares and Orion sagas: Inazuma Eleven 3 (LEVEL-5) with the fan patch “Great Road of Heroes 3.1”. Patch authorship: not verified; the base and the patch's additions can't be separated.",
  "Creados para InaZurvivors: efectos de supertécnicas, efectos de sonido, iconos de elemento, orbes, música «Generada» e interfaz.": "Made for InaZurvivors: special move effects, sound effects, element icons, orbs, “Generated” music and interface.",
  "Redes sociales": "Social media",
  "Sobre el desarrollador": "About the developer",
  "AstraStorm también ha creado otros videojuegos.": "AstraStorm has also made other video games.",
  "Enlaces oficiales": "Official links",
  "Sin cuenta, InaZurvivors no recopila datos personales: tu progreso se guarda solo en este navegador. Con cuenta online (Google) se guardan tu correo de Google (privado), tu nombre, tus marcas y tu guardado.": "Without an account, InaZurvivors collects no personal data: your progress is only saved in this browser. With an online account (Google) your Google email (private), your name, your records and your save are stored.",
