  "WASD o flechas (o el joystick táctil / mando). Las técnicas se lanzan solas: tú solo te colocas. ¡Pruébalo aquí!": "WASD or arrows (or the touch joystick / gamepad). Techniques fire by themselves: you just position yourself. Try it here!",
