  "Teclas 1, 2 y 3. Ofensiva: más daño y más riesgo. Equilibrada: neutra. Defensiva: menos daño recibido. Toca una:": "Keys 1, 2 and 3. Offensive: more damage and more risk. Balanced: neutral. Defensive: less damage taken. Tap one:",
