  "{x1}Precio y reglas": "{x1}Price and rules",
  "Los futbolistas especiales solo salen aquí, con {x1} Comunes, Raros y Épicos de relleno. Se paga con fichas de evento: cada partida en Rango S o X te da tantas como fichas normales mientras dura el evento.": "The special players only come from here, with {x1} Commons, Rares and Epics as filler. It's paid with event tokens: every run on Rank S or X gives you as many as normal tokens while the event lasts.",
