  "Ver el Sector": "See the Sector",
  "El fútbol necesita orden. A partir de hoy, el Sector Quinto decide cómo se juega cada partido.": "Football needs order. From today on, the Fifth Sector decides how every match is played.",
  "Únete a nosotros… o intenta resistir. Cada semana veremos qué bando juega mejor.": "Join us… or try to resist. Every week we'll see which side plays better.",
  "Bienvenido al Sector Quinto. Aquí el fútbol se juega como yo digo.": "Welcome to the Fifth Sector. Here football is played the way I say.",
  "Acata mis decretos y tu bando ganará.": "Obey my decrees and your side will win.",
  "La Resistencia… Veremos cuánto aguanta vuestro viento.": "The Resistance… We'll see how long your wind lasts.",
  "Rebélate si quieres: el Sector Quinto también sabe jugar duro.": "Rebel if you want: the Fifth Sector knows how to play hard too.",
