  "sus estadísticas (Aura legendaria)": "its stats (legendary Aura)",
  "Cada plaza de tu equipo tiene ahora una <b>{x1}</b> {x2} <b>{x3}</b>. Ahí pones a otro futbolista de tu colección para que apoye al de la plaza. El Aura no juega: lo potencia.": "Every slot of your team now has a <b>{x1}</b> {x2} <b>{x3}</b>. There you put another player from your collection to support the one in the slot. The Aura doesn't play: it powers them up.",
  "Solo pueden ser Aura los <b>Legendarios, Míticos y Leyendas</b>.": "Only <b>Legendaries, Mythics and Legends</b> can be an Aura.",
  "Una por futbolista. No se gasta nada: tu colección no cambia.": "One per player. Nothing is spent: your collection doesn't change.",
  "El Aura suma el <b>{x1}%</b> {x2} <b>{x3}</b> a las mismas del portador.": "The Aura adds <b>{x1}%</b> {x2} <b>{x3}</b> to the same ones of the carrier.",
  "Ejemplo: Tiro 90 + Aura con Tiro 95 » 90 + 14 = <b>104</b>.": "Example: Kick 90 + Aura with Kick 95 » 90 + 14 = <b>104</b>.",
  "Lo propio sigue en 99 como máximo; con el Aura, hasta <b>120</b>, y en el combate se nota.": "Own stats still max out at 99; with the Aura, up to <b>120</b>, and you feel it in battle.",
  "En el radar, lo que aporta el Aura se ve en <b style=\"color:#7ff6ff\">cian</b>.": "On the radar, what the Aura gives shows in <b style=\"color:#7ff6ff\">cyan</b>.",
  "Si los dos tienen historia (técnica conjunta, amistad, familia o rivalidad), el Aura da el <b>{x1}%</b>{x2} <b>♥</b>.": "If the two share a story (joint technique, friendship, family or rivalry), the Aura gives <b>{x1}%</b>{x2} <b>♥</b>.",
  "Axel y Shawn, Mark y Nathan, Jude y Celia, Arion y Riccardo...": "Axel and Shawn, Mark and Nathan, Jude and Celia, Arion and Riccardo...",
  "Estar en el mismo equipo no basta.": "Being on the same team isn't enough.",
  "El portador hereda <b>{x1}</b> del Aura: una empieza la partida en una ranura extra y la otra llega como carta al subir de nivel. No sustituyen a las suyas.": "The carrier inherits <b>{x1}</b> from the Aura: one starts the run in an extra slot and the other comes as a card when levelling up. They don't replace their own.",
  "Sus técnicas del elemento del Aura hacen <b>+{x1}%</b>.": "Their techniques of the Aura's element deal <b>+{x1}%</b>.",
  "Con el Aura puede lanzar <b>{x1}</b>: Axel con Shawn de Aura, Fuego cruzado.": "With the Aura they can use <b>{x1}</b>: Axel with Shawn as Aura, Crossfire.",
  "Cómo equiparla:": "How to equip it:",
  "toca «+ AURA» y elige en tu colección, o arrastra la carta encima.": "tap “+ AURA” and choose from your collection, or drag the card on top.",
