  "+1,5% daño por cada compañero del mismo elemento que el capitán": "+1.5% damage for each teammate of the captain's element",
  "Blindaje": "Armour",
  "-0,5 daño en cada golpe que recibe el capitán por nivel (como mucho la mitad del golpe)": "-0.5 damage on every hit the captain takes per level (at most half the hit)",
  "Resistencia a jefes": "Boss resistance",
  "-3% daño de los ataques de jefes y minijefes por nivel (máx. -15%)": "-3% damage from boss and mini-boss attacks per level (max -15%)",
  "Botiquín": "First-aid kit",
  "+12% curación de bolas de arroz y chocolate por nivel (máx. +48%)": "+12% healing from rice balls and chocolate per level (max +48%)",
  "Ventaja inicial": "Head start",
  "Empiezas la partida con un 20% de la experiencia del primer nivel por nivel (máx. 80%)": "You start the run with 20% of the first level's experience per level (max 80%)",
  "Ojo para lo raro": "Eye for the rare",
  "+4% probabilidad de objetos especiales (Revivir, Barrera, cofres...) por nivel (máx. +16%)": "+4% special item chance (Revive, Barrier, chests...) per level (max +16%)",
  "Imán de botín": "Loot magnet",
  "El Imán también atrae las bolsas de monedas, las fichas y los cofres del campo": "The Magnet also pulls in the coin bags, tokens and chests on the pitch",
  "Potenciador de daño": "Damage booster",
  "El objeto «Daño» da un +5% más por nivel (de +50% a +75%)": "The “Damage” item gives +5% more per level (from +50% to +75%)",
  "Recarga turbo": "Turbo cooldown",
  "El objeto «Recarga» recarga un 4% más por nivel (de -40% a -60%)": "The “Cooldown” item recharges 4% more per level (from -40% to -60%)",
  "Espíritu despierto": "Awakened spirit",
  "-3 s de recarga de la definitiva de tu Espíritu Guerrero por nivel (de 30 s a 15 s)": "-3 s cooldown on your Fighting Spirit's ultimate per level (from 30 s to 15 s)",
  "+3% probabilidad de ganar 1 Ficha EG extra al terminar una partida de 3 minutos o más (máx. 15%)": "+3% chance to earn 1 extra EG Token when finishing a run of 3 minutes or more (max 15%)",
  "Pizarra avanzada": "Advanced board",
  "Potencia la formación activa por nivel: ofensiva +1% daño, equilibrada +2% combinadas, defensiva -1% daño recibido (máx. 5)": "Boosts the active formation per level: offensive +1% damage, balanced +2% combined, defensive -1% damage taken (max 5)",
