  "La imagen es demasiado pesada incluso reducida. Prueba con otra.": "The image is too heavy even after shrinking. Try another one.",
  "Estrella de héroe {x1} de {HERO_STARS_MAX}: +{x2}% daño, +{x3}% vida y +1 a todas sus estadísticas": "Hero star {x1} of {HERO_STARS_MAX}: +{x2}% damage, +{x3}% HP and +1 to all their stats",
  "{x1}: el límite de sus estadísticas sube de {x2} a {x3}": "{x1}: their stat cap goes up from {x2} to {x3}",
  "{x1}: estadísticas hasta {x2} y {x3} puntos de entrenamiento": "{x1}: stats up to {x2} and {x3} training points",
  "Técnica de HÉROE: {x1}": "HERO technique: {x1}",
